    private AndroidI18n() {}

    public static String t(String source) {
        if (source == null || source.isEmpty()) return source;
        Map<String, String> messages = SOURCE_MESSAGES.get(currentMessageLocale());
        if (messages == null) return source;
        String translated = messages.get(source);
        return translated != null ? translated : source;
    }

    public static Locale currentLocale() {
        Locale locale = null;
        LocaleListCompat appLocales = AppCompatDelegate.getApplicationLocales();
        if (!appLocales.isEmpty()) locale = appLocales.get(0);
        return locale != null ? locale : Locale.getDefault();
    }

    public static String currentMessageLocale() {
        Locale locale = currentLocale();
        String language = locale.getLanguage();
        String script = locale.getScript();
        String country = locale.getCountry();
        if ("fr".equalsIgnoreCase(language)) return "fr";
        if ("es".equalsIgnoreCase(language)) return "es";
        if ("zh".equalsIgnoreCase(language)) {
            if ("Hant".equalsIgnoreCase(script)) return "en";
            if ("TW".equalsIgnoreCase(country) || "HK".equalsIgnoreCase(country) || "MO".equalsIgnoreCase(country)) return "en";
            return "zh-Hans";
        }
        return "en";
    }

    public static boolean isSimplifiedChinese() {
        return "zh-Hans".equals(currentMessageLocale());
    }
